<div id="zoomModal" class="fixed inset-0 bg-black bg-opacity-90 hidden justify-center items-center z-50 p-4 transition-opacity duration-300 opacity-0">
  <div class="relative max-w-4xl w-full" onclick="event.stopPropagation()">
    <button onclick="closeModal()" class="absolute -top-10 right-0 text-white hover:text-red-500 text-3xl z-10 transition-colors">
      <i class="fas fa-times"></i>
    </button>
    <img id="zoomImage" class="w-full max-h-[90vh] object-contain rounded shadow-lg transform scale-95 transition-transform duration-300">
  </div>
</div>

<!-- Font Awesome for icons -->
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">

<script>
 // Fungsi untuk membuka modal zoom
 function openModal(src) {
    const modal = document.getElementById('zoomModal');
    const img = document.getElementById('zoomImage');
    
    img.src = src;
    modal.classList.remove('hidden');
    
    // Trigger reflow untuk memastikan animasi berjalan
    void modal.offsetWidth;
    
    modal.classList.add('flex');
    modal.style.opacity = '1';
    img.classList.remove('scale-95');
    img.classList.add('scale-100');
    
    // Blok scroll body saat modal terbuka
    document.body.style.overflow = 'hidden';
  }

  // Fungsi untuk menutup modal zoom
  function closeModal() {
    const modal = document.getElementById('zoomModal');
    const img = document.getElementById('zoomImage');
    
    modal.style.opacity = '0';
    img.classList.remove('scale-100');
    img.classList.add('scale-95');
    
    setTimeout(() => {
      modal.classList.remove('flex');
      modal.classList.add('hidden');
      
      // Kembalikan scroll body
      document.body.style.overflow = '';
    }, 300);
  }

  // Tambahkan event listener untuk semua gambar yang bisa di-zoom
  document.addEventListener('DOMContentLoaded', function() {
    const zoomableImages = document.querySelectorAll('.cursor-zoom-in img');
    
    zoomableImages.forEach(img => {
      img.addEventListener('click', function(e) {
        e.stopPropagation();
        openModal(this.src);
      });
    });
  });
</script>